function graph_params = funnel_graph_params()
% Settings of the funnel graph, as in MPC-Graph (Atasoy et al., 2023). The
% funnels themselves are generated by generate_funnels.m (sampling until
% coverage, tangential squares grown into rectangles).

% waypoint between two funnels: CLOSEST or CENTROID (of the overlap)
graph_params.REF = 'CENTROID';

% Dijkstra edge cost: 'C2C' center to center, 'C2I2C' center to
% intersection to center, 'C2I2CWA' 'C2I2C' + 1/(intersection area)
graph_params.DIJKSTRA_COST = 'C2I2CWA';
end
